def two_sum_sorted(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        s = nums[left] + nums[right]
        if s == target:
            return [left, right]
        if s < target:
            left += 1
        else:
            right -= 1
    return []

# Remove duplicates from sorted array in place: returns new length
def remove_duplicates(nums):
    if not nums:
        return 0
    slow = 0
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1
            nums[slow] = nums[fast]
    return slow + 1

// Sorted two-sum: O(n) time, O(1) space
static int[] twoSumSorted(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left < right) {
        int sum = nums[left] + nums[right];
        if (sum == target) return new int[] { left, right };
        if (sum < target) left++;
        else right--;
    }
    return new int[0];
}

// Sorted two-sum: O(n) time, O(1) space
vector<int> twoSumSorted(const vector<int>& nums, int target) {
    int left = 0, right = (int)nums.size() - 1;
    while (left < right) {
        int sum = nums[left] + nums[right];
        if (sum == target) return { left, right };
        if (sum < target) left++;
        else right--;
    }
    return {};
}

// Fixed window: max sum of k consecutive elements. O(n)
function maxSumK(nums, k) {
  let sum = 0;
  for (let i = 0; i < k; i++) sum += nums[i];
  let best = sum;
  for (let i = k; i < nums.length; i++) {
    sum += nums[i] - nums[i - k];
    best = Math.max(best, sum);
  }
  return best;
}

// Variable window: longest substring without repeating characters. O(n)
function lengthOfLongestSubstring(s) {
  const seen = new Set();
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    while (seen.has(s[right])) seen.delete(s[left++]);
    seen.add(s[right]);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

// Variable window: longest substring without repeating characters. O(n)
static int lengthOfLongestSubstring(String s) {
    Set<Character> seen = new HashSet<>();
    int left = 0, best = 0;
    for (int right = 0; right < s.length(); right++) {
        while (seen.contains(s.charAt(right))) seen.remove(s.charAt(left++));
        seen.add(s.charAt(right));
        best = Math.max(best, right - left + 1);
    }
    return best;
}

// Variable window: longest substring without repeating characters. O(n)
int lengthOfLongestSubstring(const string& s) {
    unordered_set<char> seen;
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        while (seen.count(s[right])) seen.erase(s[left++]);
        seen.insert(s[right]);
        best = max(best, right - left + 1);
    }
    return best;
}

// Classic: index of target or -1. O(log n) time, O(1) space
function binarySearch(a, target) {
  let lo = 0, hi = a.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (a[mid] === target) return mid;
    if (a[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

// Boundary template: first index where a[i] >= x (lower bound)
function lowerBound(a, x) {
  let lo = 0, hi = a.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (a[mid] >= x) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

// Search on the answer: Koko eating bananas
function minEatingSpeed(piles, h) {
  let lo = 1, hi = Math.max(...piles);
  while (lo < hi) {
    const k = lo + Math.floor((hi - lo) / 2);
    const hours = piles.reduce((s, p) => s + Math.ceil(p / k), 0);
    if (hours <= h) hi = k;
    else lo = k + 1;
  }
  return lo;
}

