def min_eating_speed(piles, h):
    lo, hi = 1, max(piles)
    while lo < hi:
        k = lo + (hi - lo) // 2
        hours = sum((p + k - 1) // k for p in piles)
        if hours <= h:
            hi = k
        else:
            lo = k + 1
    return lo

